	/// The bundled incidents as milestones, dated and ready to land.
	static var seededIncidents: [L2beatMilestone] {
		incidents.compactMap { seed in
			guard let date = L2beatNewsParse.date(fromISO: seed.day) else { return nil }
			return L2beatMilestone(
				projectID: seed.project, title: seed.title, summary: seed.summary,
				kind: .incident, day: seed.day, date: date, url: seed.url)
		}
	}

	/// The chains the demo furnishes, with L2BEAT's real readings and real sentences —
	/// so the furnished demo shows what the feature actually shows.
	static let demoChains: [String] = [
		"arbitrum",
		"base",
		"linea",
	]
